document.addEventListener("DOMContentLoaded",function(){fetch(`../locales/${lang}.json`).then(e=>e.json()).then(e=>{let t,r,o=e.posts,n=new URLSearchParams(window.location.search).get("name"),l=!1;for(var a=0;a<o.length;a++)if(o[a].title.toLowerCase()==n){r=o[a],t=parseInt(o[a].id),l=!0;break}if(l){document.title=r.title,document.querySelector("section.site-hero.inner-page.overlay").style.setProperty("background-image",`url('../images/${r.main_image}')`);const e=document.querySelector("section.blog-intro");e.querySelector("h3").innerText=r.title,e.querySelector("span > span").innerText=r.tag;const t=document.querySelector("section.blog-article");t.querySelector("h4").innerText=r.title;let o=0;t.querySelectorAll("h6").forEach(e=>{e.innerText=r.headings[o],++o}),o=0,t.querySelectorAll("p").forEach(e=>{e.innerText=r.paragraphs[o],++o}),o=0,t.querySelectorAll("img").forEach(e=>{e.src="../images/"+r.images[o],++o}),document.querySelector("section.bg-image.overlay").style.setProperty("background-image",`url('../images/${r.main_image}')`)}else window.open("404.html","_self");let i=[];const c=o.length-1,s=e=>{let r;do{r=Math.floor(Math.random()*c)}while(e.includes(r)||r===t-1);return r};for(let e=0;e<2;e++)i.push(s(i));const u=document.querySelector("section.blog-item-feature");let m=0;u.querySelectorAll(".blog-item").forEach(e=>{const t=i[m];e.querySelector("span").innerText=o[t].tag,e.querySelector("h5 > a").innerText=o[t].title,e.querySelector("img").src="../images/"+o[t].main_image,e.querySelectorAll("a").forEach(e=>{e.setAttribute("href","post.html?name="+o[t].title.toLowerCase())}),++m})})});